from taf.sw.dcap.rd.schemas.base import SchemaField, SchemaObject


class TracersCMV1(SchemaObject):
    tracer_id = SchemaField(name="id")
    name = SchemaField(name="name")
    type = SchemaField(name="type")
    unsupported_major_swversions = SchemaField(name="unsupported_major_swversions")
    post_processors = SchemaField(name="post_processors")
    availability = SchemaField(name="availability")

    def __init__(self, tracer_id, name, type, unsupported_major_swversions, post_processors, availability):
        self.tracer_id = tracer_id
        self.name = name
        self.type = type
        self.unsupported_major_swversions = unsupported_major_swversions
        self.post_processors = post_processors
        self.availability = availability

        super(TracersCMV1, self).__init__()
